// Some portions generated by Claude

// Each repository keeps its own SPARQL Update draft: an update typed for one repository is never offered, ready to
// run, in another repository or on another server.
const test = require('node:test');
const assert = require('node:assert/strict');
const { createFormBrowserHarness } = require('./form-browser-harness.js');

const DEFAULT_UPDATE = 'INSERT DATA {\n\t<http://exampleSub> <http://examplePred> <http://exampleObj> .\n}';

// data-workbench-server-identity as WorkbenchServlet writes it: the server's digest, then this browser session's scope.
const SERVER_1 = 'sha256:' + '1'.repeat(64) + ':6f1c2c3e-0d7e-4b8f-9a51-0c8e7f3b2a11';
const SERVER_1_NEXT_SESSION = 'sha256:' + '1'.repeat(64) + ':a4d0b9e2-37c5-4e1a-8f62-5b9d1c0e7f34';
const SERVER_2 = 'sha256:' + '2'.repeat(64) + ':6f1c2c3e-0d7e-4b8f-9a51-0c8e7f3b2a11';

/** YASQE as far as its draft goes: it fills the editor from storage[persistent] and writes the text back on blur. */
function fakeYasqe(harness, storage) {
    let editor = null;
    harness.context.YASQE = {
        defaults: {},
        Autocompleters: { prefixes: {} },
        registerAutocompleter() {},
        fromTextArea(textarea, options) {
            const persistent = options.persistent;
            const id = typeof persistent === 'function' ? persistent() : persistent;
            let value = id && Object.prototype.hasOwnProperty.call(storage, id) ? storage[id] : textarea.value;
            editor = {
                getValue: () => value,
                setValue: (next) => { value = next; },
                blur() {
                    if (id) {
                        storage[id] = value;
                    }
                },
                refresh() {},
                save() {},
                getWrapperElement: () => harness.registerElement('div'),
                on() {},
                getOption: () => false,
                setOption() {},
                // CodeMirror writes the editor's text back into the textarea it leaves.
                toTextArea() { textarea.value = value; }
            };
            return editor;
        }
    };
    return () => editor;
}

function updatePage(storage) {
    const harness = createFormBrowserHarness({ globals: { namespaces: {} } });
    const app = harness.registerElement('div', { id: 'workbench-app' });
    harness.document.body.appendChild(app);
    const editor = fakeYasqe(harness, storage);
    harness.loadScripts(['yasqeHelper.js', 'update.js']);
    let page = null;
    /**
     * Open the Update page of repository on server, as the router does, and return its editor. In place, the page
     * keeps the textarea it had, as Lit re-renders the same template for another repository.
     */
    return function open(server, repository, inPlace) {
        app.setAttribute('data-workbench-server-identity', server);
        app.setAttribute('data-workbench-repository-id', repository);
        if (!inPlace) {
            page = harness.registerElement('div');
            // The template's text, which is also the textarea's default value.
            page.appendChild(harness.registerElement('textarea', { id: 'update', value: '\n\t' }));
            app.appendChild(page);
        }
        const close = harness.context.workbench.update.mount(page);
        return { editor: editor(), close };
    };
}

test('an update typed for one repository is not offered in another repository', () => {
    const open = updatePage({});

    const first = open(SERVER_1, 'repo-a');
    first.editor.setValue('DELETE WHERE { ?s ?p ?o }');
    first.editor.blur();
    first.close();

    const other = open(SERVER_1, 'repo-b');
    assert.equal(other.editor.getValue(), DEFAULT_UPDATE, 'repo-b starts from the example, not repo-a\'s DELETE');
    other.close();

    const again = open(SERVER_1, 'repo-a');
    assert.equal(again.editor.getValue(), 'DELETE WHERE { ?s ?p ?o }', 'repo-a keeps its own draft');
    again.close();
});

test('switching repository on the Update page does not carry the update to the next repository', () => {
    const open = updatePage({});

    const first = open(SERVER_1, 'repo-a');
    first.editor.setValue('DELETE WHERE { ?s ?p ?o }');
    first.editor.blur();
    first.close();

    const other = open(SERVER_1, 'repo-b', true);
    assert.equal(other.editor.getValue(), DEFAULT_UPDATE, 'repo-b starts from the example, not repo-a\'s DELETE');
    other.close();
});

test('the same repository ID on another server has its own update draft', () => {
    const open = updatePage({});

    const first = open(SERVER_1, 'repo-a');
    first.editor.setValue('CLEAR ALL');
    first.editor.blur();
    first.close();

    const other = open(SERVER_2, 'repo-a');
    assert.equal(other.editor.getValue(), DEFAULT_UPDATE);
    other.close();
});

test('a repository keeps its update draft in the next browser session', () => {
    const open = updatePage({});

    const first = open(SERVER_1, 'repo-a');
    first.editor.setValue('DELETE WHERE { ?s ?p ?o }');
    first.editor.blur();
    first.close();

    const later = open(SERVER_1_NEXT_SESSION, 'repo-a');
    assert.equal(later.editor.getValue(), 'DELETE WHERE { ?s ?p ?o }');
    later.close();
});

test('the draft every repository used to share is not offered in any repository', () => {
    const open = updatePage({ update: 'DROP ALL' });

    const page = open(SERVER_1, 'repo-a');
    assert.equal(page.editor.getValue(), DEFAULT_UPDATE);
    page.close();
});
